function resolveFile(reqUrl) {
    let cleanUrl = reqUrl.split('?')[0].split('#')[0];
    if (cleanUrl === '' || cleanUrl === '/') cleanUrl = '/index.html';

    if (STATIC_MAP[cleanUrl] && fs.existsSync(STATIC_MAP[cleanUrl])) {
        return STATIC_MAP[cleanUrl];
    }
    if (CWD_MAP[cleanUrl] && fs.existsSync(CWD_MAP[cleanUrl])) {
        return CWD_MAP[cleanUrl];
    }

    const p1 = path.join(__dirname, cleanUrl);
    if (fs.existsSync(p1) && !fs.statSync(p1).isDirectory()) return p1;

    const p2 = path.join(process.cwd(), cleanUrl);
    if (fs.existsSync(p2) && !fs.statSync(p2).isDirectory()) return p2;

    return null;
}

function handleRequest(req, res) {
    let reqUrl = req.url.split('?')[0];
    if (reqUrl === '/') reqUrl = '/index.html';

    const filePath = resolveFile(reqUrl);

    if (filePath) {
        const ext = path.extname(filePath).toLowerCase();
        const contentType = MIME_TYPES[ext] || 'application/octet-stream';
        const isStatic = ext !== '.html';
        const cacheControl = isStatic ? 'public, max-age=31536000, immutable' : 'public, max-age=0, must-revalidate';

        fs.readFile(filePath, (err, content) => {
            if (!err) {
                res.writeHead(200, {
                    'Content-Type': contentType,
                    'Cache-Control': cacheControl,
                    'X-Content-Type-Options': 'nosniff'
                });
                res.end(content);
                return;
            }

            if (INLINE_ASSETS[reqUrl]) {
                res.writeHead(200, {
                    'Content-Type': contentType,
                    'Cache-Control': cacheControl,
                    'X-Content-Type-Options': 'nosniff'
                });
                res.end(INLINE_ASSETS[reqUrl]);
                return;
            }

            res.writeHead(500, { 'Content-Type': 'text/plain' });
            res.end('500 Server Error: ' + err.code);
        });
        return;
    }

    if (INLINE_ASSETS[reqUrl]) {
        const ext = path.extname(reqUrl).toLowerCase() || '.html';
        const contentType = MIME_TYPES[ext] || 'text/html; charset=utf-8';
        const isStatic = ext !== '.html';
        const cacheControl = isStatic ? 'public, max-age=31536000, immutable' : 'public, max-age=0, must-revalidate';

        res.writeHead(200, {
            'Content-Type': contentType,
            'Cache-Control': cacheControl,
            'X-Content-Type-Options': 'nosniff'
        });
        res.end(INLINE_ASSETS[reqUrl]);
        return;
    }

    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('404 Not Found: ' + reqUrl);
}

module.exports = (req, res) => handleRequest(req, res);

if (require.main === module) {
    const server = http.createServer(handleRequest);
    server.on('error', (err) => {
        if (err.code === 'EADDRINUSE') {
            console.log(`Port ${PORT} in use, trying ${PORT + 1}...`);
            server.listen(PORT + 1);
        } else {
            console.error('Server error:', err);
        }
    });
    server.listen(PORT, () => {
        console.log(`Street Runner server running at http://localhost:${PORT}/`);
    });
}
